ALTER TABLE claim ADD COLUMN tags VARCHAR(1000) NOT NULL DEFAULT '';

-- Every tag ever used on a sheet, each once: the sheet shows a due-total for each.
CREATE TABLE sheet_tag (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    tag      VARCHAR(100) NOT NULL,
    CONSTRAINT sheet_tag_unique UNIQUE (sheet_id, tag)
);
-- How many proofs a claim has; it starts at 0. A claim whose due is above the sheet's proof threshold
-- in force on its date cannot be settled or approved while it has none.
ALTER TABLE claim ADD COLUMN proofs INT DEFAULT 0 NOT NULL;
-- A claim's status log: one line per status it has had, oldest first, with who made the change, the
-- sheet's today then and the claim's due as it was then (null when it had none). A claim already there
-- starts with no lines.
CREATE TABLE claim_log (
    claim_id BIGINT NOT NULL REFERENCES claim(id),
    seq INT NOT NULL,
    status VARCHAR(20) NOT NULL,
    by_user VARCHAR(200) NOT NULL,
    on_date DATE NOT NULL,
    due DECIMAL(14, 2),
    PRIMARY KEY (claim_id, seq)
);
